    System.out.println("TRAS 10 Segunos: " + gestorEfectosExpiracion.obtenerReglas().obtenerIntervaloMovimiento());

    //PRUEBAS PUNTUACION DOBLE DURACION
    System.out.println("\n-----PRUEBAS PUNTUACION DOBLE DURACION-----");
